let ctx;
let centerX, centerY;
let palettes = [
	['#000000', '#c4d451', '#ff009c', '#015df6', '#8600b7', '#ffef00', '#ffffff'],
	['#119da4', '#d00000', '#ffba08', '#2d4fb6', '#e7f3f8', '#e78325', '#6dcb5a'],
	['#f1ca0a', '#1248ae', '#de183c', '#ffe9c2', '#ec4e20', '#f991cc', '#63be93'],
];
let shapes = [];
const REFRESH_FRAME = 260;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
}

function draw() {
	background('#000');
	for (let i of shapes) {
		i.run();
	}

	if (frameCount % REFRESH_FRAME === 1) {
		refreshLayout()
	}
}

function refreshLayout() {
	shapes = [];
	let tileCount = int(random(4, 9));
	let palette = random(palettes);
	addShapes_grid(centerX, centerY, width, tileCount, palette);
}

function addShapes_grid(x, y, w, n, palette) {
	let cellW = w / n;
	let lineLength = cellW * 0.09;
	let lineThickness = cellW * 0.02;
	let margin = cellW * 0.15;
	for (let i = 0; i <= n; i++) {
		for (let j = 0; j <= n; j++) {
			let cellX = i * cellW + x - ((w - cellW) / 2);
			let cellY = j * cellW + y - ((w - cellW) / 2);

			if (i != n && j != n) {
				drawTile(cellX, cellY, cellW, palette);
			}
		}
	}
}

function drawTile(x, y, w, palette) {
	let tAngle = int(random(4)) * (TAU / 4);
	let p = shuffle([...palette], true);
	let shapeCount = 3;
	shapes.push(new RectMotion(x, y, w, w, 0, int(random(20)), p[0]));
	for (let i = 0; i < shapeCount; i++) {
		drawSubPattern(x, y, w, p[i + 1]);
	}
}

function drawSubPattern(x, y, w, clr) {
	let n = int(random(1, 4));
	let ww = w / n;
	let shapeType = int(random(3));
	let scaleFactor = random(0.2, 0.8);
	let ang = int(random(4)) * (TAU / 4);

	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			let xx = (i * ww) - ((w - ww) / 2) + x;
			let yy = (j * ww) - ((w - ww) / 2) + y;
			let t = int(random(20, 100))
			if (shapeType === 0) {
				shapes.push(new RectMotion(xx, yy, ww * scaleFactor, ww * scaleFactor, 0, t, clr));
			} else if (shapeType === 1) {
				shapes.push(new CircleMotion(xx, yy, ww * scaleFactor, t, clr));

			} else if (shapeType === 2) {
				shapes.push(new RectMotion(xx, yy, ww * 0.8 * scaleFactor, ww * 0.8 * scaleFactor, PI / 4, t, clr));

			}
		}
	}
}

function drawLune(x, y, d, r1, r2) {
	let radius = d * 0.5;
	let h1 = map(r1, 0, 1, -1, 1) * radius;
	let h2 = map(r2, 0, 1, -1, 1) * radius;

	push();
	translate(x, y);
	beginShape();
	for (let a = 0; a <= PI; a += PI / 60) {
		vertex(radius * cos(a), h1 * sin(a));
	}
	for (let a = PI; a <= TAU; a += PI / 60) {
		vertex(radius * cos(a), h2 * sin(a));
	}
	endShape(CLOSE);
	pop();
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

/*------------------------------------------------------------------------------------------*/


class CircleMotion {
	constructor(x, y, d, t, clr) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.clr = clr;
		this.motionType = int(random(4));
		this.timer = -t;
		this.phase1 = 40;
		this.phase2 = this.phase1 + 90;
		this.phase3 = this.phase2 + 40;

		this.circleAngle = int(random(4)) * (TAU / 4);

		this.arcAngle = 0;
		this.scaleX = random([-1, 1]);

		this.maxShift = this.d * 1.5;
		this.shift = this.maxShift;
		this.d_mType1 = 0;
		this.ratioW = 1;
		this.ratioH = 1;

		this.holeD = this.d;

		this.lunaRatio1 = 1;
		this.lunaRatio2 = 0;
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.circleAngle);
		strokeWeight(0);
		fill(this.clr);

		if (this.motionType === 0) {
			scale(this.scaleX, 1);
			arc(0, 0, this.d, this.d, 0, this.arcAngle, PIE);
		} else if (this.motionType === 1) {
			ellipse(this.shift, 0, this.d_mType1 * this.ratioW, this.d_mType1 * this.ratioH);
		} else if (this.motionType === 2) {
			let cc = 180;
			beginShape();
			for (let i = 0; i < cc; i++) {
				let a = map(i, 0, cc, 0, TAU);
				let r = this.d / 2;
				vertex(r * cos(a), r * sin(a));
			}
			beginContour();
			for (let i = 0; i < cc; i++) {
				let a = map(i, cc, 0, 0, TAU);
				let r = this.holeD / 2;
				vertex(r * cos(a), r * sin(a));
			}
			endContour();
			endShape();
		} else if (this.motionType === 3) {
			drawLune(0, 0, this.d, this.lunaRatio1, this.lunaRatio2);
		}
		pop();
	}

	update() {
		this.timer++;
		if (0 < this.timer && this.timer < this.phase1) {
			let n = norm(this.timer, 0, this.phase1 - 1);
			this.arcAngle = lerp(0, TAU, easeInOutCubic(n));
			this.d_mType1 = lerp(0, this.d, easeInOutCubic(n));
			this.shift = lerp(this.maxShift, 0, easeInOutCubic(n));
			this.ratioW = lerp(1, 1.25, sin(easeInOutCubic(n) * PI));
			this.ratioH = lerp(1, 0.5, sin(easeInOutCubic(n) * PI));
			this.holeD = lerp(this.d, 0, easeInOutCubic(n));
			this.lunaRatio2 = lerp(0, 1, easeInOutCubic(n));

		} else if (this.phase1 < this.timer && this.timer < this.phase2) {

		} else if (this.phase2 < this.timer && this.timer < this.phase3) {
			let n = norm(this.timer, this.phase2, this.phase3 - 1);
			this.arcAngle = lerp(TAU, 0, easeInOutCubic(n));
			this.d_mType1 = lerp(this.d, 0, easeInOutCubic(n));
			this.shift = lerp(0, this.maxShift, easeInOutCubic(n));
			this.ratioW = lerp(1, 1.25, sin(easeInOutCubic(n) * PI));
			this.ratioH = lerp(1, 0.5, sin(easeInOutCubic(n) * PI));
			this.holeD = lerp(0, this.d, easeInOutCubic(n));
			this.lunaRatio2 = lerp(1, 0, easeInOutCubic(n));
		}
	}

	run() {
		this.display();
		this.update();
	}
}

